// loadConfig pattern from config.cjs
function loadConfig(cwd) {
  const configPath = path.join(cwd, '.planning', 'config.json');
  try {
    const raw = fs.readFileSync(configPath, 'utf-8');
    const parsed = JSON.parse(raw);
    return {
      mode: parsed.mode || 'yolo',
      granularity: parsed.granularity || 'standard',
      model_profile: parsed.model_profile || 'balanced',
      commit_docs: parsed.commit_docs !== false,
    };
  } catch {
    return { mode: 'yolo', granularity: 'standard',
             model_profile: 'balanced', commit_docs: true };
  }
}

// STATE.md is Markdown with structured sections
// state.cjs parses it with regex, not a Markdown library

function parseStateMd(content) {
  // Extract 'Current Position' section
  const posMatch = content.match(
    /## Current Position([\s\S]*?)(?=\n## |$)/
  );
  // Extract phase, plan numbers from the text
  const phaseMatch = posMatch[1].match(
    /Phase:\s*(\d+)/
  );
  return { phase: phaseMatch[1] };
}
